import React from 'react';
import { useOutletContext } from 'react-router-dom';

const Cloud_SubPage = ({ index, title }) => {
  const context = useOutletContext();
  const cloudData = context?.cloud?.data;
  const pData = cloudData ? cloudData[index] : null;

  console.log("SubPage Index:", index, "Data at index:", pData);

  return (
    <div className="workspace-container">
      {/* Navbar is in the parent CloudPage, so we removed it here to prevent duplication */}
      <div className="summary-box">
        <h3>{title}</h3>
        {pData ? (
          <div className="telemetry-data">
            <p className="status-badge">● Status: {pData.status}</p>
            <pre className="json-view">{JSON.stringify(pData, null, 2)}</pre>
          </div>
        ) : (
          <div className="empty-state">
            <p>Data stream offline. Please sync from the Infrastructure Dashboard.</p>
          </div>
        )}
      </div>
    </div>
  );
};
export default Cloud_SubPage;
